### 创建简单柱状图

```javascript
// 设置画布尺寸
const width = 400;
const height = 300;
const margin = { top: 20, right: 20, bottom: 30, left: 40 };

// 数据
const data = [
  { month: 'Jan', value: 30 },
  { month: 'Feb', value: 80 },
  { month: 'Mar', value: 45 },
  { month: 'Apr', value: 60 },
  { month: 'May', value: 20 },
  { month: 'Jun', value: 90 },
  { month: 'Jul', value: 55 }
];

// 创建 SVG
const svg = d3.select('#chart')
  .append('svg')
  .attr('width', width)
  .attr('height', height);

// 创建比例尺
const x = d3.scaleBand()
  .domain(data.map(d => d.month))
  .range([margin.left, width - margin.right])
  .padding(0.2);

const y = d3.scaleLinear()
  .domain([0, d3.max(data, d => d.value)])
  .range([height - margin.bottom, margin.top]);

// 绘制坐标轴
svg.append('g')
  .attr('transform', `translate(0, ${height - margin.bottom})`)
  .call(d3.axisBottom(x));

svg.append('g')
  .attr('transform', `translate(${margin.left}, 0)`)
  .call(d3.axisLeft(y));

// 绘制柱子
svg.selectAll('.bar')
  .data(data)
  .join('rect')
  .attr('class', 'bar')
  .attr('x', d => x(d.month))
  .attr('y', d => y(d.value))
  .attr('width', x.bandwidth())
  .attr('height', d => y(0) - y(d.value))
  .attr('fill', 'steelblue');
```

### 交互式工具提示

```javascript
// 添加工具提示
d3.select('#chart')
  .append('div')
  .attr('class', 'tooltip')
  .style('opacity', 0);

// 在柱子上添加交互
svg.selectAll('.bar')
  .data(data)
  .join('rect')
  .attr('class', 'bar')
  .attr('x', d => x(d.month))
  .attr('y', d => y(d.value))
  .attr('width', x.bandwidth())
  .attr('height', d => y(0) - y(d.value))
  .attr('fill', 'steelblue')
  .on('mouseover', function(event, d) {
    d3.select(this).attr('fill', 'orange');
    d3.select('.tooltip')
      .transition()
      .duration(200)
      .style('opacity', .9);
    d3.select('.tooltip')
      .html(`${d.month}: ${d.value}`)
      .style('left', (event.pageX + 10) + 'px')
      .style('top', (event.pageY - 28) + 'px');
  })
  .on('mouseout', function(d) {
    d3.select(this).attr('fill', 'steelblue');
    d3.select('.tooltip')
      .transition()
      .duration(500)
      .style('opacity', 0);
  });
```

