### Promise

```javascript
// 创建 Promise
function fetchUser() {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            const success = true;
            if (success) {
                resolve({ name: "John", age: 30 });
            } else {
                reject(new Error("获取用户失败"));
            }
        }, 1000);
