  "compilerOptions": {
    "strict": true
  }
}
```

### 2. 避免使用 any

```typescript
// 不好
function processData(data: any) {
    return data.value;
}

// 好
function processData<T>(data: T): T {
    return data;
}
```

### 3. 使用类型推断

```typescript
// 不必要的类型注解
let name: string = "John";

// 更好：让 TS 推断
let name = "John";
```

### 4. 优先使用 interface 定义对象

```typescript
// 推荐
interface User {
    name: string;
    age: number;
}

// 也可以，但不推荐用于对象
