### 案例 3: 调试渲染问题

```javascript
// React 组件不更新

// 1. 使用 React DevTools
// - 检查 props 和 state
// - 查看组件层级

// 2. 添加调试日志
function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    console.log('useEffect triggered:', userId);
    fetchUser(userId).then(data => {
      console.log('fetch result:', data);
      setUser(data);
    });
  }, [userId]); // 依赖项

  console.log('render:', user);
