### 2. CRUD 操作

#### 插入文档

```javascript
// 插入单个文档
db.users.insertOne({
  name: "Alice",
  email: "alice@example.com",
  age: 28,
  createdAt: new Date()
})

// 插入多个文档
db.users.insertMany([
  { name: "Bob", email: "bob@example.com", age: 32 },
  { name: "Charlie", email: "charlie@example.com", age: 25 }
])

// 返回插入的 ID
const result = db.users.insertOne({ name: "David" })
print(result.insertedId)  // ObjectId
```

#### 查询文档

```javascript
// 查询所有
db.users.find()

// 查询单个
db.users.findOne({ name: "Alice" })

// 条件查询
db.users.find({ age: { \$gt: 30 } })  // 年龄大于 30
db.users.find({ age: { \$gte: 18, \$lte: 65 } })  // 18-65

// 逻辑操作
db.users.find({
  \$or: [
    { age: { \$lt: 18 } },
    { role: "admin" }
  ]
})

// 数组查询
db.users.find({ tags: "mongodb" })  // 包含
db.users.find({ tags: { \$all: ["mongodb", "nodejs"] } })  // 同时包含
db.users.find({ tags: { \$size: 3 } })  // 数组长度

// 嵌套文档查询
db.users.find({ "address.city": "New York" })

// 正则表达式
db.users.find({ name: /^A/i })  // 名字以 A 开头
```

#### 更新文档

```javascript
// 更新单个文档
db.users.updateOne(
  { name: "Alice" },
  { \$set: { age: 29 } }
)

// 更新多个文档
db.users.updateMany(
  { role: "user" },
  { \$set: { status: "active" } }
)

// 替换文档
db.users.replaceOne(
  { name: "Alice" },
  { name: "Alice Smith", email: "alice@example.com" }
)

// 更新操作符
db.users.updateOne(
  { _id: ObjectId("...") },
  {
    \$set: { age: 30 },           // 设置字段
    \$unset: { tempField: 1 },    // 删除字段
    \$inc: { loginCount: 1 },     // 增加数值
    \$mul: { score: 2 },          // 乘以数值
    \$rename: { name: "fullName" } // 重命名字段
  }
)

// 数组操作
db.users.updateOne(
  { _id: ObjectId("...") },
  {
    \$push: { tags: "mongodb" },     // 添加到数组
    \$addToSet: { tags: "nodejs" },  // 避免重复
    \$pull: { tags: "old" },         // 从数组删除
    \$pop: { tags: 1 }               // 删除首/尾元素
  }
)
```

#### 删除文档

```javascript
// 删除单个文档
db.users.deleteOne({ name: "Alice" })

// 删除多个文档
db.users.deleteMany({ status: "inactive" })

// 删除所有文档（清空集合）
db.users.deleteMany({})
```

### 3. 聚合管道

聚合管道是 MongoDB 最强大的功能之一，用于数据转换和分析。

```javascript
// 基础聚合
db.orders.aggregate([
  // \$match: 过滤文档
  { \$match: { status: "completed" } },

  // \$group: 分组聚合
  { \$group: {
    _id: "\$userId",
    totalAmount: { \$sum: "\$amount" },
    count: { \$sum: 1 },
    avgAmount: { \$avg: "\$amount" }
  }},

  // \$sort: 排序
  { \$sort: { totalAmount: -1 } },

  // \$limit: 限制结果
  { \$limit: 10 }
])

// 复杂聚合示例
db.sales.aggregate([
  // 展开数组
  { \$unwind: "\$items" },

  // 查找关联
  { \$lookup: {
    from: "products",
    localField: "items.productId",
    foreignField: "_id",
    as: "product"
  }},

  // 过滤
  { \$match: { "product.category": "electronics" } },

  // 分组统计
  { \$group: {
    _id: "\$product.category",
    totalRevenue: { \$sum: { \$multiply: ["\$items.price", "\$items.quantity"] } },
    avgPrice: { \$avg: "\$items.price" }
  }},

  // 投影（选择字段）
  { \$project: {
    category: "\$_id",
    revenue: "\$totalRevenue",
    avgPrice: { \$round: ["\$avgPrice", 2] },
    _id: 0
  }}
])
```

### 4. 索引

```javascript
// 创建索引
db.users.createIndex({ email: 1 })  // 升序
db.users.createIndex({ name: -1 })  // 降序
db.users.createIndex({ age: 1, name: 1 })  // 复合索引

// 唯一索引
db.users.createIndex({ email: 1 }, { unique: true })

// 稀疏索引（只索引包含该字段的文档）
db.users.createIndex({ phone: 1 }, { sparse: true })

// TTL 索引（自动过期）
db.sessions.createIndex({ createdAt: 1 }, { expireAfterSeconds: 3600 })

// 文本索引
db.articles.createIndex({ title: "text", content: "text" })
db.articles.find({ \$text: { \$search: "mongodb tutorial" } })

// 地理空间索引
db.places.createIndex({ location: "2dsphere" })
db.places.find({
  location: {
    \$near: {
      \$geometry: { type: "Point", coordinates: [-73.9667, 40.78] },
      \$maxDistance: 1000
    }
  }
})

// 查看索引
db.users.getIndexes()

// 删除索引
db.users.dropIndex("email_1")
```

