## Node.js 集成

### 使用 amqplib

```javascript
const amqp = require('amqplib');

async function connect() {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();
  return { connection, channel };
}
```

### 消息模式

#### 1. Work Queue（工作队列）

```javascript
// 生产者
async function sendTask() {
  const { connection, channel } = await connect();

  const queue = 'task_queue';
  await channel.assertQueue(queue, { durable: true });

  const message = 'Hello RabbitMQ!';
  channel.sendToQueue(
    queue,
    Buffer.from(message),
    { persistent: true }
  );

  console.log('Sent:', message);

  await channel.close();
  await connection.close();
}

// 消费者
async function worker() {
  const { connection, channel } = await connect();

  const queue = 'task_queue';
  await channel.assertQueue(queue, { durable: true });

  // 公平分发（预取计数）
  channel.prefetch(1);

  channel.consume(queue, (msg) => {
    const content = msg.content.toString();
    console.log('Received:', content);

    // 模拟处理
    setTimeout(() => {
      console.log('Done');
      channel.ack(msg);
    }, 1000);
  }, { noAck: false });
}
```

#### 2. Publish/Subscribe（发布订阅）

```javascript
// 生产者（发送日志）
async function emitLog() {
  const { connection, channel } = await connect();

  const exchange = 'logs';
  await channel.assertExchange(exchange, 'fanout', { durable: false });

  const message = 'Info: Hello World!';
  channel.publish(exchange, '', Buffer.from(message));

  console.log('Sent:', message);

  await channel.close();
  await connection.close();
}

// 消费者（接收日志）
async function receiveLog() {
  const { connection, channel } = await connect();

  const exchange = 'logs';
  await channel.assertExchange(exchange, 'fanout', { durable: false });

  // 临时队列
  const q = await channel.assertQueue('', { exclusive: true });

  // 绑定到交换机
  await channel.bindQueue(q.queue, exchange, '');

  channel.consume(q.queue, (msg) => {
    const content = msg.content.toString();
    console.log('Received:', content);
  }, { noAck: true });
}
```

#### 3. Routing（路由）

```javascript
// 生产者
async function emitLogDirect() {
  const { connection, channel } = await connect();

  const exchange = 'direct_logs';
  await channel.assertExchange(exchange, 'direct', { durable: false });

  const severity = process.argv[2] || 'info';
  const message = 'Hello World!';

  channel.publish(exchange, severity, Buffer.from(message));

  console.log('Sent %s: %s', severity, message);

  await channel.close();
  await connection.close();
}

// 消费者
async function receiveLogDirect() {
  const { connection, channel } = await connect();

  const exchange = 'direct_logs';
  await channel.assertExchange(exchange, 'direct', { durable: false });

  const q = await channel.assertQueue('', { exclusive: true });

  const severities = process.argv.slice(2);
  severities.forEach((severity) => {
    channel.bindQueue(q.queue, exchange, severity);
  });

  channel.consume(q.queue, (msg) => {
    const severity = msg.fields.routingKey;
    const content = msg.content.toString();
    console.log('Received %s: %s', severity, content);
  }, { noAck: true });
}
```

