### 3. Orders Subgraph

```javascript
// orders/index.js
const typeDefs = gql`
  type Order @key(fields: "id") {
    id: ID!
    userId: ID!
    items: [OrderItem!]!
    total: Float!
    status: OrderStatus!
    createdAt: String!
    # 需要从 Users Subgraph 获取
    user: User
    # 需要外部字段计算
    products: [Product!]!
      @requires(fields: "items { productId }")
  }

  enum OrderStatus {
    PENDING
    PROCESSING
    SHIPPED
    DELIVERED
    CANCELLED
  }

  type OrderItem {
    productId: ID!
    quantity: Int!
    price: Float!
    # 引用 Products Subgraph
    product: Product
  }

  extend type Query {
    orders(userId: ID!): [Order!]!
    order(id: ID!): Order
  }

  extend type User @key(fields: "id") {
    id: ID! @external
    orders: [Order!]!
  }

  extend type Product @key(fields: "id") {
    id: ID! @external
  }
`;

const resolvers = {
  Query: {
    orders: (_, { userId }) => [
      {
        id: '1',
        userId,
        items: [
          { productId: 'p1', quantity: 2, price: 99.99 }
        ],
        total: 199.98,
        status: 'PROCESSING',
        createdAt: '2024-01-01T00:00:00Z'
      }
    ],
    order: (_, { id }) => ({
      id,
      userId: '1',
      items: [],
      total: 0,
      status: 'PENDING',
      createdAt: '2024-01-01T00:00:00Z'
    })
  },
  User: {
    orders: (user) => [
      {
        id: '1',
        userId: user.id,
        items: [],
        total: 0,
        status: 'PENDING',
        createdAt: '2024-01-01T00:00:00Z'
      }
    ]
  },
  Order: {
    user: (order) => ({
      __typename: 'User',
      id: order.userId
    }),
