```python
# 微分段策略管理器
class MicroSegmentationManager:
    def __init__(self):
        self.policies = {}
        self.service_graph = {}

    def create_policy(self, policy_id, source, destination, rules):
        """创建微分段策略"""
        self.policies[policy_id] = {
            'source': source,      # 源服务/网段
            'destination': destination,  # 目标服务/网段
            'rules': rules,        # 访问规则
            'enabled': True
        }

    def evaluate_traffic(self, source_ip, dest_ip, port, protocol):
        """评估流量是否允许通过"""
        # 查找匹配的策略
        for policy_id, policy in self.policies.items():
            if not policy['enabled']:
                continue

            if self._matches(policy['source'], source_ip) and \
               self._matches(policy['destination'], dest_ip):

                # 检查规则
                for rule in policy['rules']:
                    if rule['port'] == port and rule['protocol'] == protocol:
                        return {
                            'allowed': rule['action'] == 'allow',
                            'policy': policy_id
                        }

        # 默认拒绝
        return {'allowed': False, 'policy': 'default-deny'}

    def _matches(self, pattern, ip):
        """检查 IP 是否匹配模式"""
        import ipaddress
        if '/' in pattern:
            return ipaddress.ip_address(ip) in ipaddress.ip_network(pattern)
        return ip == pattern

# 使用示例
manager = MicroSegmentationManager()

# 创建策略：只允许前端服务访问后端 API
manager.create_policy(
    policy_id='frontend-to-backend',
    source='10.1.1.0/24',  # 前端网段
    destination='10.2.1.10',  # 后端服务 IP
    rules=[
        {'port': 8080, 'protocol': 'tcp', 'action': 'allow'},
        {'port': 8443, 'protocol': 'tcp', 'action': 'allow'}
    ]
)

# 评估流量
result = manager.evaluate_traffic('10.1.1.5', '10.2.1.10', 8080, 'tcp')
print(f"Traffic allowed: {result['allowed']}")
