### 存储加密

```python
# 使用 AES-256-GCM 加密敏感数据
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.backends import default_backend
import os

class DataEncryption:
    def __init__(self, key=None):
        """初始化加密器，使用 AES-256-GCM"""
        self.key = key or os.urandom(32)  # 256-bit key
        self.aesgcm = AESGCM(self.key)

    def encrypt(self, plaintext, associated_data=None):
        """加密数据"""
        # 生成随机 nonce
        nonce = os.urandom(12)

        # 加密
        ciphertext = self.aesgcm.encrypt(
            nonce,
            plaintext.encode('utf-8'),
            associated_data
        )

        # 返回 nonce + ciphertext
        return {
            'nonce': nonce.hex(),
            'ciphertext': ciphertext.hex()
        }

    def decrypt(self, nonce_hex, ciphertext_hex, associated_data=None):
        """解密数据"""
        nonce = bytes.fromhex(nonce_hex)
        ciphertext = bytes.fromhex(ciphertext_hex)

        try:
            plaintext = self.aesgcm.decrypt(
                nonce,
                ciphertext,
                associated_data
            )
            return plaintext.decode('utf-8')
        except Exception as e:
            raise ValueError(f"Decryption failed: {e}")

# 使用示例
encryption = DataEncryption()

# 加密数据
encrypted = encryption.encrypt(
    "Sensitive user data: PII information",
    associated_data=b"user-123"
)
print(f"Encrypted: {encrypted}")

# 解密数据
decrypted = encryption.decrypt(
    encrypted['nonce'],
    encrypted['ciphertext'],
    associated_data=b"user-123"
)
print(f"Decrypted: {decrypted}")
