// 结构化审计日志系统
class AuditLogger {
  constructor() {
    this.events = [];
    this.sinks = [];
  }

  // 记录安全事件
  log(event) {
    const auditEvent = {
      timestamp: new Date().toISOString(),
      event_type: event.type,
      actor: {
        id: event.userId,
        type: event.userType,  // user, service, system
        ip_address: event.ipAddress,
        user_agent: event.userAgent
      },
      action: {
        operation: event.operation,  // create, read, update, delete
        resource: event.resource,
        resource_type: event.resourceType
      },
      result: {
        status: event.status,  // success, failure
        error_code: event.errorCode,
        reason: event.reason
      },
      context: {
        session_id: event.sessionId,
        request_id: event.requestId,
        correlation_id: event.correlationId
      },
      risk_score: this.calculateRiskScore(event)
    };

    // 添加到事件队列
    this.events.push(auditEvent);

    // 异步发送到 sinks
    this.sendToSinks(auditEvent);

    return auditEvent;
  }

  // 计算风险评分
  calculateRiskScore(event) {
    let score = 0;

    // 高风险操作
    const highRiskOps = ['delete', 'drop', 'truncate', 'grant'];
    if (highRiskOps.includes(event.operation.toLowerCase())) {
      score += 50;
    }

    // 敏感资源
    const sensitiveResources = ['user', 'password', 'key', 'secret', 'token'];
    if (sensitiveResources.some(r => event.resource.includes(r))) {
      score += 30;
    }

    // 失败操作增加风险
    if (event.status === 'failure') {
      score += 20;
    }

    // 异常位置
    if (event.isUnusualLocation) {
      score += 40;
    }

    return Math.min(100, score);
  }

  // 添加输出目标
  addSink(sink) {
    this.sinks.push(sink);
  }

  // 发送到所有 sinks
  async sendToSinks(event) {
    for (const sink of this.sinks) {
      try {
        await sink.write(event);
      } catch (error) {
        console.error('Failed to write to sink:', error);
      }
    }
  }
}

// 日志 sinks
class ConsoleSink {
  async write(event) {
    console.log(JSON.stringify(event, null, 2));
  }
}

class FileSink {
  constructor(filename) {
    this.filename = filename;
    this.fs = require('fs').promises;
  }

  async write(event) {
    await this.fs.appendFile(
      this.filename,
      JSON.stringify(event) + '\n'
    );
  }
}

class SIEMSink {
  constructor(endpoint, apiKey) {
    this.endpoint = endpoint;
    this.apiKey = apiKey;
  }

  async write(event) {
    await fetch(this.endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': this.apiKey
      },
      body: JSON.stringify(event)
    });
  }
}

