```python
# 基于机器学习的异常检测
from sklearn.ensemble import IsolationForest
import numpy as np
from datetime import datetime, timedelta

class SecurityAnomalyDetector:
    def __init__(self):
        self.models = {}
        self.baseline_data = {}

    def train_baseline(self, user_id, historical_events):
        """训练用户行为基线"""
        features = []

        for event in historical_events:
            features.append([
                event['hour_of_day'],
                event['day_of_week'],
                event['request_count'],
                event['unique_resources'],
                event['avg_response_time'],
                event['failed_attempts']
            ])

        X = np.array(features)

        # 训练 Isolation Forest 模型
        model = IsolationForest(
            contamination=0.1,
            random_state=42
        )
        model.fit(X)

        self.models[user_id] = model
        self.baseline_data[user_id] = {
            'feature_mean': np.mean(X, axis=0),
            'feature_std': np.std(X, axis=0)
        }

    def detect_anomaly(self, user_id, current_event):
        """检测异常行为"""
        if user_id not in self.models:
            return {'anomaly': False, 'reason': 'No baseline established'}

        model = self.models[user_id]
        baseline = self.baseline_data[user_id]

        # 提取当前事件特征
        features = np.array([[
            current_event['hour_of_day'],
            current_event['day_of_week'],
            current_event['request_count'],
            current_event['unique_resources'],
            current_event['avg_response_time'],
            current_event['failed_attempts']
        ]])

        # 预测
        prediction = model.predict(features)[0]
        anomaly_score = model.score_samples(features)[0]

        # 计算偏差
        z_scores = np.abs(
            (features[0] - baseline['feature_mean']) /
            (baseline['feature_std'] + 1e-6)
        )

        # 判断异常
        is_anomaly = prediction == -1 or np.any(z_scores > 3)

        return {
            'anomaly': is_anomaly,
            'anomaly_score': float(anomaly_score),
            'z_scores': z_scores.tolist(),
            'reason': self._get_anomaly_reason(z_scores)
        }

    def _get_anomaly_reason(self, z_scores):
        """获取异常原因"""
        features = [
            'hour_of_day', 'day_of_week', 'request_count',
            'unique_resources', 'avg_response_time', 'failed_attempts'
        ]

        anomalies = [
            (features[i], score)
            for i, score in enumerate(z_scores)
            if score > 3
        ]

        if not anomalies:
            return 'Anomaly detected by ML model'

        return ', '.join([
            f'{feature} (z-score: {score:.2f})'
            for feature, score in anomalies
        ])

# 使用示例
detector = SecurityAnomalyDetector()

# 训练基线（需要历史数据）
historical_events = [
    {'hour_of_day': 9, 'day_of_week': 1, 'request_count': 50,
     'unique_resources': 10, 'avg_response_time': 100, 'failed_attempts': 0},
    # ... 更多历史事件
]

detector.train_baseline('user-123', historical_events)

# 检测当前事件
current_event = {
    'hour_of_day': 3,  # 凌晨 3 点
    'day_of_week': 1,
    'request_count': 500,  # 异常高的请求数
    'unique_resources': 50,
    'avg_response_time': 500,
    'failed_attempts': 50
}

result = detector.detect_anomaly('user-123', current_event)
print(f"Anomaly detected: {result['anomaly']}")
print(f"Reason: {result['reason']}")
