```python
# STRIDE 威胁建模分析
class STRIDEGuide:
    """
    STRIDE 威胁分类：
    - Spoofing (欺骗): 伪装成合法用户
    - Tampering (篡改): 修改数据或代码
    - Repudiation (抵赖): 否认执行过操作
    - Information Disclosure (信息泄露): 暴露敏感信息
    - Denial of Service (拒绝服务): 使服务不可用
    - Elevation of Privilege (权限提升): 获得更高权限
    """

    def __init__(self):
        self.threats = []

    def analyze_data_flow(self, dfd):
        """分析数据流图中的威胁"""
        for element in dfd['elements']:
            for threat in self._identify_threats(element):
                self.threats.append({
                    'element': element['id'],
                    'threat': threat,
                    'category': threat['category'],
                    'severity': threat['severity'],
                    'mitigation': threat['mitigation']
                })

        return self.threats

    def _identify_threats(self, element):
        """识别元素上的威胁"""
        threats = []
        element_type = element['type']

        if element_type == 'external_entity':
            # 外部实体：欺骗、信息泄露
            threats.extend([
                {
                    'category': 'Spoofing',
                    'description': '攻击者伪装成合法用户',
                    'severity': 'high',
                    'mitigation': '实施强认证（MFA、证书）'
                },
                {
                    'category': 'Information Disclosure',
                    'description': '敏感信息泄露给未授权方',
                    'severity': 'medium',
                    'mitigation': '加密传输和存储、访问控制'
                }
            ])

        elif element_type == 'process':
            # 进程：篡改、权限提升
            threats.extend([
                {
                    'category': 'Tampering',
                    'description': '代码或数据被修改',
                    'severity': 'high',
                    'mitigation': '代码签名、完整性检查、输入验证'
                },
                {
                    'category': 'Elevation of Privilege',
                    'description': '获得超出授权的权限',
                    'severity': 'high',
                    'mitigation': '最小权限原则、权限隔离、审计'
                }
            ])

        elif element_type == 'data_store':
            # 数据存储：篡改、信息泄露、拒绝服务
            threats.extend([
                {
                    'category': 'Tampering',
                    'description': '存储的数据被修改',
                    'severity': 'high',
                    'mitigation': '加密存储、访问控制、审计日志'
                },
                {
                    'category': 'Information Disclosure',
                    'description': '敏感数据被访问',
                    'severity': 'high',
                    'mitigation': '加密、字段级权限、数据脱敏'
                },
                {
                    'category': 'Denial of Service',
                    'description': '存储不可用',
                    'severity': 'medium',
                    'mitigation': '备份、限流、冗余'
                }
            ])

        elif element_type == 'data_flow':
            # 数据流：欺骗、篡改、信息泄露、抵赖
            threats.extend([
                {
                    'category': 'Spoofing',
                    'description': '消息源被伪造',
                    'severity': 'medium',
                    'mitigation': '消息认证码（MAC）、数字签名'
                },
                {
                    'category': 'Tampering',
                    'description': '传输中的数据被修改',
                    'severity': 'high',
                    'mitigation': 'TLS、端到端加密'
                },
                {
                    'category': 'Repudiation',
                    'description': '用户否认发送过消息',
                    'severity': 'low',
                    'mitigation': '数字签名、审计日志'
                }
            ])

        return threats

# 使用示例
analyzer = STRIDEGuide()

# 定义数据流图
dfd = {
    'elements': [
        {'id': 'user', 'type': 'external_entity'},
        {'id': 'api_gateway', 'type': 'process'},
        {'id': 'auth_service', 'type': 'process'},
        {'id': 'database', 'type': 'data_store'},
        {'id': 'flow1', 'type': 'data_flow', 'source': 'user', 'dest': 'api_gateway'},
        {'id': 'flow2', 'type': 'data_flow', 'source': 'api_gateway', 'dest': 'auth_service'},
        {'id': 'flow3', 'type': 'data_flow', 'source': 'auth_service', 'dest': 'database'}
    ]
}

# 分析威胁
threats = analyzer.analyze_data_flow(dfd)

# 生成报告
for threat in threats:
    print(f"\nElement: {threat['element']}")
    print(f"Category: {threat['category']}")
    print(f"Description: {threat['description']}")
    print(f"Severity: {threat['severity']}")
    print(f"Mitigation: {threat['mitigation']}")
```

