### 3. 安全代码审查

```javascript
// 安全代码审查检查点
class SecurityCodeReview {
  static checkAuthentication(req, res, next) {
    // 检查 1：认证是否存在
    if (!req.session || !req.session.userId) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    // 检查 2：会话是否有效
    if (req.session.expiresAt < Date.now()) {
      req.session.destroy();
      return res.status(401).json({ error: 'Session expired' });
    }

    // 检查 3：MFA 是否验证
    if (!req.session.mfaVerified) {
      return res.status(403).json({ error: 'MFA required' });
    }

    next();
  }

  static checkAuthorization(requiredRole) {
    return (req, res, next) => {
      // 检查 4：用户是否有必要权限
      if (!req.session.roles.includes(requiredRole)) {
        // 记录未授权访问尝试
        logger.warn('Unauthorized access attempt', {
          userId: req.session.userId,
          requiredRole,
          userRoles: req.session.roles
        });
        return res.status(403).json({ error: 'Forbidden' });
      }

      next();
    };
  }

  static validateInput(req, res, next) {
    // 检查 5：输入验证
    const { username, email } = req.body;

    // 白名单验证
    if (!/^[a-zA-Z0-9_]{3,20}$/.test(username)) {
      return res.status(400).json({ error: 'Invalid username' });
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return res.status(400).json({ error: 'Invalid email' });
    }

    // 长度限制
    if (username.length > 20) {
      return res.status(400).json({ error: 'Username too long' });
    }

    next();
  }

  static preventSQLInjection(query, params) {
    // 检查 6：参数化查询
    // 好的做法：使用参数化
    const goodQuery = 'SELECT * FROM users WHERE id = $1';
    // 避免：字符串拼接
    // const badQuery = `SELECT * FROM users WHERE id = '${userId}'`;

    return { query, params };
  }
}
