## 性能分析基础

### 性能指标

```python
# 核心性能指标
class PerformanceMetrics:
    """
    关键性能指标 (KPI)：
    - 延迟 (Latency): 请求响应时间
    - 吞吐量 (Throughput): 单位时间处理的请求数
    - 资源利用率: CPU、内存、I/O、网络使用率
    - 错误率: 失败请求的百分比
    - 饱和度: 系统负载程度
    """

    @staticmethod
    def measure_latency(func):
        """测量函数执行延迟"""
        import time
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            result = func(*args, **kwargs)
            end = time.perf_counter()

            latency_ms = (end - start) * 1000

            # 记录延迟分布
            wrapper.latency_history.append(latency_ms)

            # 计算百分位数
            if len(wrapper.latency_history) > 100:
                p50 = np.percentile(wrapper.latency_history, 50)
                p95 = np.percentile(wrapper.latency_history, 95)
                p99 = np.percentile(wrapper.latency_history, 99)

                print(f"Latency - p50: {p50:.2f}ms, p95: {p95:.2f}ms, p99: {p99:.2f}ms")

            return result

        wrapper.latency_history = []
        return wrapper

    @staticmethod
    def measure_throughput(duration_sec=10):
        """测量系统吞吐量"""
        import time
        import threading

        request_count = 0
        lock = threading.Lock()
        stop_event = threading.Event()

        def worker():
            nonlocal request_count
            while not stop_event.is_set():
                # 模拟请求处理
                time.sleep(0.01)
                with lock:
                    request_count += 1

        # 启动多个工作线程
        threads = [threading.Thread(target=worker) for _ in range(10)]
        for t in threads:
            t.start()

        # 运行指定时间
        time.sleep(duration_sec)
        stop_event.set()

        for t in threads:
            t.join()

        throughput = request_count / duration_sec
        print(f"Throughput: {throughput:.2f} requests/sec")
        return throughput

    @staticmethod
    def calculate_resource_usage():
        """计算资源使用率"""
        import psutil

        # CPU 使用率
        cpu_percent = psutil.cpu_percent(interval=1)

        # 内存使用率
        memory = psutil.virtual_memory()
        memory_percent = memory.percent

        # 磁盘 I/O
        disk_io = psutil.disk_io_counters()
        disk_read_mb = disk_io.read_bytes / (1024 * 1024)
        disk_write_mb = disk_io.write_bytes / (1024 * 1024)

        # 网络 I/O
        net_io = psutil.net_io_counters()
        net_sent_mb = net_io.bytes_sent / (1024 * 1024)
        net_recv_mb = net_io.bytes_recv / (1024 * 1024)

        return {
            'cpu_percent': cpu_percent,
            'memory_percent': memory_percent,
            'disk_io': {'read_mb': disk_read_mb, 'write_mb': disk_write_mb},
            'net_io': {'sent_mb': net_sent_mb, 'recv_mb': net_recv_mb}
        }
