## CPU 优化

### CPU 亲和性

```python
# 设置 CPU 亲和性优化缓存命中率
import os
import psutil

class CPUAffinityManager:
    def __init__(self):
        self.cpu_count = os.cpu_count()
        self.physical_cores = self._get_physical_cores()

    def _get_physical_cores(self):
        """获取物理核心数（考虑超线程）"""
        import multiprocessing
        return multiprocessing.cpu_count()

    def set_process_affinity(self, pid, cores):
        """设置进程 CPU 亲和性"""
        p = psutil.Process(pid)
        p.cpu_affinity(cores)
        print(f"Process {pid} affinity set to cores {cores}")

    def optimize_for_cache(self, num_workers=None):
        """优化 CPU 亲和性以提高缓存命中率"""
        if num_workers is None:
            num_workers = self.physical_cores

        # 将工作线程绑定到同一物理核心的逻辑核心
        # 这可以提高 L1/L2 缓存的命中率
        affinity_map = []

        for i in range(num_workers):
            # 将线程分配到不同物理核心
            # 假设超线程是 (0, N), (1, N+1), ... 的模式
            physical_core = i % (self.physical_cores // 2)
            logical_core = physical_core

            affinity_map.append([logical_core])

        return affinity_map

    def set_irq_affinity(self, irq, cores):
        """设置 IRQ 中断亲和性"""
        # 写入 /proc/irq/<irq>/smp_affinity
        affinity_mask = 0
        for core in cores:
            affinity_mask |= (1 << core)

        hex_mask = format(affinity_mask, 'x')

        try:
            with open(f'/proc/irq/{irq}/smp_affinity', 'w') as f:
                f.write(hex_mask)
            print(f"IRQ {irq} affinity set to cores {cores}")
        except Exception as e:
            print(f"Failed to set IRQ affinity: {e}")

# 使用示例
affinity_mgr = CPUAffinityManager()

# 为 Web 服务器设置 CPU 亲和性
# 假设系统有 8 个核心
worker_affinity = affinity_mgr.optimize_for_cache(num_workers=4)

for i, cores in enumerate(worker_affinity):
    print(f"Worker {i}: bind to cores {cores}")

# 将中断处理分配到特定核心
# affinity_mgr.set_irq_affinity(irq=24, cores=[0, 1])
