### CPU 缓存优化

```c
// CPU 缓存优化示例
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ARRAY_SIZE 1024 * 1024 * 64
#define ITERATIONS 100

// 缓存行填充，避免伪共享
typedef struct {
    long value;
    char padding[64 - sizeof(long)];  // 填充到缓存行大小（64 字节）
} cache_line_aligned_t;

// 优化前：缓存不友好的访问模式
void cache_unfriendly_access(int *array, size_t size) {
    clock_t start = clock();

    for (int iter = 0; iter < ITERATIONS; iter++) {
        // 跨步访问导致大量缓存未命中
        for (size_t i = 0; i < size; i += 16) {
            array[i] *= 2;
        }
    }

    clock_t end = clock();
    double elapsed = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Cache unfriendly: %.2f seconds\n", elapsed);
}

// 优化后：缓存友好的访问模式
void cache_friendly_access(int *array, size_t size) {
    clock_t start = clock();

    for (int iter = 0; iter < ITERATIONS; iter++) {
        // 顺序访问最大化缓存利用
        for (size_t i = 0; i < size; i++) {
            array[i] *= 2;
        }
    }

    clock_t end = clock();
    double elapsed = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Cache friendly: %.2f seconds\n", elapsed);
}

// 数据重组提高缓存命中率
typedef struct {
    int id;
    float x, y, z;
    int type;
} particle_t;

// AoS (Array of Structures) - 缓存不友好
void process_aos(particle_t *particles, size_t count) {
    for (size_t i = 0; i < count; i++) {
        // 每次访问只使用部分数据，浪费缓存带宽
        particles[i].x *= 1.1f;
        particles[i].y *= 1.1f;
        particles[i].z *= 1.1f;
    }
}

// SoA (Structure of Arrays) - 缓存友好
typedef struct {
    int *id;
    float *x, *y, *z;
    int *type;
} particle_soa_t;

void process_soa(particle_soa_t *particles, size_t count) {
    // 分别处理每个数组，提高缓存命中率
    for (size_t i = 0; i < count; i++) {
        particles->x[i] *= 1.1f;
    }
    for (size_t i = 0; i < count; i++) {
        particles->y[i] *= 1.1f;
    }
    for (size_t i = 0; i < count; i++) {
        particles->z[i] *= 1.1f;
    }
}

int main() {
    int *array = malloc(ARRAY_SIZE * sizeof(int));

    printf("Array size: %d MB\n", ARRAY_SIZE * sizeof(int) / (1024 * 1024));

    cache_unfriendly_access(array, ARRAY_SIZE);
    cache_friendly_access(array, ARRAY_SIZE);

    free(array);
    return 0;
}
```

### CPU 指令优化

```cpp
// SIMD 指令优化（AVX2）
#include <immintrin.h>
#include <stdio.h>

// 标量版本
void scalar_add(float *a, float *b, float *result, size_t n) {
    for (size_t i = 0; i < n; i++) {
        result[i] = a[i] + b[i];
    }
}

// SIMD 版本（AVX2：一次处理 8 个 float）
void simd_add(float *a, float *b, float *result, size_t n) {
    size_t i = 0;

    // 处理可被 8 整除的部分
    for (; i + 8 <= n; i += 8) {
        // 加载 8 个 float
        __m256 va = _mm256_loadu_ps(&a[i]);
        __m256 vb = _mm256_loadu_ps(&b[i]);

        // 向量加法
        __m256 vr = _mm256_add_ps(va, vb);

        // 存储结果
        _mm256_storeu_ps(&result[i], vr);
    }

    // 处理剩余元素
    for (; i < n; i++) {
        result[i] = a[i] + b[i];
    }
}

// 预取优化
void prefetch_optimized(float *a, float *b, float *result, size_t n) {
    const size_t prefetch_distance = 16;  // 预取距离

    for (size_t i = 0; i < n; i++) {
        // 预取未来数据到缓存
        if (i + prefetch_distance < n) {
            _mm_prefetch((const char*)&a[i + prefetch_distance], _MM_HINT_T0);
            _mm_prefetch((const char*)&b[i + prefetch_distance], _MM_HINT_T0);
        }

        // 处理当前数据
        __m256 va = _mm256_loadu_ps(&a[i]);
        __m256 vb = _mm256_loadu_ps(&b[i]);
        __m256 vr = _mm256_add_ps(va, vb);
        _mm256_storeu_ps(&result[i], vr);
    }
}

// 分支预测优化
int conditional_move(int x, int y, int condition) {
    // 避免：if (condition) return x; else return y;
    // 使用条件移动指令（CMOV）
    int result = y;
    asm volatile (
        "test %1, %1\n\t"
        "cmovne %2, %0"
        : "=r" (result)
        : "r" (condition), "r" (x), "0" (result)
        : "cc"
    );
    return result;
}
