## 内存优化

### 内存分配策略

```python
# 内存池优化
import mmap
import ctypes
import numpy as np

class MemoryPool:
    """预分配内存池，减少动态分配开销"""

    def __init__(self, block_size, num_blocks):
        self.block_size = block_size
        self.num_blocks = num_blocks
        self.pool_size = block_size * num_blocks

        # 使用 mmap 分配大块内存
        self.pool = mmap.mmap(
            -1,  # 匿名映射
            self.pool_size,
            flags=mmap.MAP_PRIVATE | mmap.MAP_ANONYMOUS
        )

        # 管理空闲块
        self.free_blocks = [i * block_size for i in range(num_blocks)]
        self.allocated_blocks = {}

    def allocate(self, size):
        """分配内存块"""
        if size > self.block_size:
            raise ValueError(f"Size {size} exceeds block size {self.block_size}")

        if not self.free_blocks:
            raise MemoryError("No free blocks available")

        offset = self.free_blocks.pop()
        self.allocated_blocks[offset] = size

        # 返回内存视图
        return memoryview(self.pool)[offset:offset + size]

    def deallocate(self, mem_view):
        """释放内存块"""
        offset = mem_view.obj_start()
        if offset in self.allocated_blocks:
            del self.allocated_blocks[offset]
            self.free_blocks.append(offset)

# 对象池复用
class ObjectPool:
    """对象池复用，减少对象创建/销毁开销"""

    def __init__(self, factory, initial_size=10):
        self.factory = factory
        self.pool = []
        self.in_use = set()

        # 预创建对象
        for _ in range(initial_size):
            self.pool.append(self.factory())

    def acquire(self):
        """获取对象"""
        if self.pool:
            obj = self.pool.pop()
            self.in_use.add(id(obj))
            return obj
        else:
            # 池为空，创建新对象
            obj = self.factory()
            self.in_use.add(id(obj))
            return obj

    def release(self, obj):
        """释放对象回池"""
        if id(obj) in self.in_use:
            self.in_use.remove(id(obj))

            # 重置对象状态
            if hasattr(obj, 'reset'):
                obj.reset()

            self.pool.append(obj)

# 使用示例
class DatabaseConnection:
    def __init__(self):
        self.connected = False

    def connect(self):
        self.connected = True

    def query(self, sql):
        if not self.connected:
            raise RuntimeError("Not connected")
        return f"Result: {sql}"

    def reset(self):
        self.connected = False

# 创建连接池
connection_pool = ObjectPool(
    factory=DatabaseConnection,
    initial_size=5
)

# 使用连接
conn = connection_pool.acquire()
conn.connect()
result = conn.query("SELECT * FROM users")
print(result)
connection_pool.release(conn)
