### 内存布局优化

```cpp
// 内存布局优化
#include <iostream>
#include <vector>
#include <chrono>

// 优化前：缓存行浪费
struct BadLayout {
    bool flag1;      // 1 byte + 7 bytes padding
    int value1;      // 4 bytes
    bool flag2;      // 1 byte + 3 bytes padding
    double value2;   // 8 bytes
    bool flag3;      // 1 byte + 7 bytes padding
};  // 总共 32 字节

// 优化后：紧凑布局
struct OptimizedLayout {
    double value2;   // 8 bytes
    int value1;      // 4 bytes
    bool flag1;      // 1 byte
    bool flag2;      // 1 byte
    bool flag3;      // 1 byte + 1 byte padding
};  // 总共 16 字节

// 位域进一步压缩
struct PackedLayout {
    double value2;   // 8 bytes
    int value1;      // 4 bytes
    unsigned flag1 : 1;  // 1 bit
    unsigned flag2 : 1;  // 1 bit
    unsigned flag3 : 1;  // 1 bit
    unsigned : 5;        // 5 bits padding
};  // 总共 16 字节

// SoA 布局（提高缓存利用率）
struct ParticlesSoA {
    std::vector<float> x, y, z;
    std::vector<int> type;

    ParticlesSoA(size_t count) {
        x.reserve(count);
        y.reserve(count);
        z.reserve(count);
        type.reserve(count);
    }

    void add_particle(float px, float py, float pz, int ptype) {
        x.push_back(px);
        y.push_back(py);
        z.push_back(pz);
        type.push_back(ptype);
    }

    // 只处理 x 坐标，缓存友好
    void process_x() {
        for (size_t i = 0; i < x.size(); i++) {
            x[i] *= 1.1f;
        }
    }
};

// 内存对齐
alignas(64) struct AlignedData {
    float data[16];
};

void benchmark_layouts() {
    const size_t count = 10000000;

    auto start = std::chrono::high_resolution_clock::now();

    std::vector<BadLayout> bad(count);
    for (auto& item : bad) {
        item.value1 = 42;
        item.value2 = 3.14;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto bad_duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

    start = std::chrono::high_resolution_clock::now();

    std::vector<OptimizedLayout> good(count);
    for (auto& item : good) {
        item.value1 = 42;
        item.value2 = 3.14;
    }

    end = std::chrono::high_resolution_clock::now();
    auto good_duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

    std::cout << "Bad layout: " << bad_duration.count() << "ms\n";
    std::cout << "Good layout: " << good_duration.count() << "ms\n";
    std::cout << "Sizeof BadLayout: " << sizeof(BadLayout) << "\n";
    std::cout << "Sizeof OptimizedLayout: " << sizeof(OptimizedLayout) << "\n";
}
