```python
# Python 垃圾回收优化
import gc
import sys

class MemoryOptimizer:
    """内存优化工具"""

    @staticmethod
    def optimize_gc():
        """优化垃圾回收行为"""
        # 获取当前 GC 阈值
        thresholds = gc.get_threshold()
        print(f"Current GC thresholds: {thresholds}")

        # 调整阈值以减少 GC 频率
        # 格式：(generation0_threshold, generation1_threshold, generation2_threshold)
        gc.set_threshold(700, 10, 10)

        # 禁用自动 GC（手动控制）
        gc.disable()

    @staticmethod
    def manual_gc():
        """手动触发垃圾回收"""
        # 收集所有代
        collected = gc.collect()

        # 只收集特定代
        # gc.collect(generation=0)

        return collected

    @staticmethod
    def find_cycles():
        """查找引用循环"""
        gc.set_debug(gc.DEBUG_SAVEALL)

        # 运行 GC
        gc.collect()

        # 获取无法回收的对象（循环引用）
        unreachable = gc.garbage

        if unreachable:
            print(f"Found {len(unreachable)} unreachable objects")
            for obj in unreachable[:10]:
                print(f"  {type(obj)}: {obj}")

        gc.garbage.clear()

    @staticmethod
    def profile_memory():
        """分析内存使用"""
        import sys
        import tracemalloc

        # 启动内存跟踪
        tracemalloc.start()

        # ... 执行代码 ...

        # 获取当前内存快照
        snapshot = tracemalloc.take_snapshot()

        # 分析内存分配
        top_stats = snapshot.statistics('lineno')

        print("Top 10 memory allocations:")
        for stat in top_stats[:10]:
            print(stat)

        tracemalloc.stop()

