### 磁盘 I/O 优化

```python
# 批量 I/O 操作
import os
import aiofiles
import asyncio

class IOOptimizer:
    """I/O 操作优化"""

    @staticmethod
    def batch_reads(files, batch_size=100):
        """批量读取文件"""
        results = {}

        for i in range(0, len(files), batch_size):
            batch = files[i:i + batch_size]

            for file_path in batch:
                try:
                    with open(file_path, 'r') as f:
                        results[file_path] = f.read()
                except Exception as e:
                    results[file_path] = None

        return results

    @staticmethod
    async def async_batch_reads(files):
        """异步批量读取"""
        async def read_file(file_path):
            try:
                async with aiofiles.open(file_path, 'r') as f:
                    return await f.read()
            except Exception as e:
                return None

        tasks = [read_file(f) for f in files]
        results = await asyncio.gather(*tasks)

        return dict(zip(files, results))

    @staticmethod
    def use_mmap(file_path):
        """使用内存映射文件"""
        with open(file_path, 'r+b') as f:
            # 内存映射
            mmapped_file = mmap.mmap(f.fileno(), 0)

            # 像访问内存一样访问文件
            content = mmapped_file.read()

            mmapped_file.close()

        return content

    @staticmethod
    def optimize_writes(data, file_path):
        """优化写入操作"""
        # 批量写入
        with open(file_path, 'w', buffering=8192) as f:
            for item in data:
                f.write(str(item))

        # 或使用一次性写入
        with open(file_path, 'w') as f:
            f.write('\n'.join(map(str, data)))

    @staticmethod
    def use_direct_io(file_path, data):
        """使用 Direct I/O（绕过系统缓存）"""
        import os

        flags = os.O_DIRECT | os.O_WRONLY | os.O_CREAT
        fd = os.open(file_path, flags)

        try:
            os.write(fd, data)
        finally:
            os.close(fd)

