```python
# 批量网络请求优化
import asyncio
import aiohttp
from typing import List

async def batch_requests(urls: List[str], batch_size=10):
    """批量请求（分批处理）"""

    async def fetch(session, url):
        try:
            async with session.get(url) as response:
                return await response.text()
        except Exception as e:
            return None

    async with aiohttp.ClientSession() as session:
        results = []

        # 分批处理
        for i in range(0, len(urls), batch_size):
            batch = urls[i:i + batch_size]

            # 并发请求
            tasks = [fetch(session, url) for url in batch]
            batch_results = await asyncio.gather(*tasks)

            results.extend(batch_results)

        return results

# 请求合并
class RequestCombiner:
    """请求合并器"""

    def __init__(self, delay_ms=10):
        self.delay_ms = delay_ms
        self.pending = []
        self.lock = asyncio.Lock()
        self.timer = None

    async def request(self, key):
        """发送请求（可能被合并）"""
        future = asyncio.Future()

        async with self.lock:
            self.pending.append((key, future))

            # 重置定时器
            if self.timer:
                self.timer.cancel()

            self.timer = asyncio.create_task(
                self._execute_after_delay()
            )

        return await future

    async def _execute_after_delay(self):
        """延迟后执行批量请求"""
        await asyncio.sleep(self.delay_ms / 1000)

        async with self.lock:
            # 收集待处理请求
            batch = self.pending.copy()
            self.pending.clear()
            self.timer = None

        # 执行批量请求
        keys = [key for key, _ in batch]
        results = await self._fetch_batch(keys)

        # 返回结果
        for (key, future), result in zip(batch, results):
            future.set_result(result)

    async def _fetch_batch(self, keys):
        """执行批量获取"""
        # 实际实现中，这里会调用后端批量 API
        return [f"result-{key}" for key in keys]
