## 性能监控

### 实时性能监控

```python
# 性能监控系统
import time
import psutil
from collections import deque
from dataclasses import dataclass
from typing import Dict, List

@dataclass
class Metric:
    name: str
    value: float
    timestamp: float
    labels: Dict[str, str]

class PerformanceMonitor:
    """性能监控器"""

    def __init__(self, window_size=60):
        self.window_size = window_size  # 保留最近 60 秒的数据
        self.metrics: Dict[str, deque] = {}

    def record(self, name: str, value: float, labels=None):
        """记录指标"""
        if labels is None:
            labels = {}

        metric = Metric(
            name=name,
            value=value,
            timestamp=time.time(),
            labels=labels
        )

        if name not in self.metrics:
            self.metrics[name] = deque(maxlen=self.window_size)

        self.metrics[name].append(metric)

    def get_metrics(self, name: str) -> List[Metric]:
        """获取指标"""
        return list(self.metrics.get(name, []))

    def get_stats(self, name: str):
        """获取统计信息"""
        metrics = self.get_metrics(name)

        if not metrics:
            return None

        values = [m.value for m in metrics]

        return {
            'count': len(values),
            'min': min(values),
            'max': max(values),
            'avg': sum(values) / len(values),
            'p50': self._percentile(values, 50),
            'p95': self._percentile(values, 95),
            'p99': self._percentile(values, 99)
        }

    def _percentile(self, values, p):
        """计算百分位数"""
        sorted_values = sorted(values)
        k = (len(sorted_values) - 1) * (p / 100)
        f = int(k)
        c = f + 1 if f < len(sorted_values) - 1 else f

        if f == c:
            return sorted_values[f]

        d = k - f
        return sorted_values[f] * (1 - d) + sorted_values[c] * d

    def collect_system_metrics(self):
        """收集系统指标"""
        # CPU
        cpu_percent = psutil.cpu_percent(interval=0.1)
        self.record('system.cpu.percent', cpu_percent)

        # 内存
        memory = psutil.virtual_memory()
        self.record('system.memory.percent', memory.percent)
        self.record('system.memory.available_mb', memory.available / (1024 * 1024))

        # 磁盘
        disk = psutil.disk_usage('/')
        self.record('system.disk.percent', disk.percent)
        self.record('system.disk.free_gb', disk.free / (1024 ** 3))

        # 网络
        net = psutil.net_io_counters()
        self.record('system.net.bytes_sent', net.bytes_sent)
        self.record('system.net.bytes_recv', net.bytes_recv)

    def start_monitoring(self, interval=1):
        """开始监控"""
        import asyncio

        async def _monitor():
            while True:
                self.collect_system_metrics()
                await asyncio.sleep(interval)

        return asyncio.create_task(_monitor())

# 性能计数器装饰器
def track_performance(monitor: PerformanceMonitor, metric_name: str):
    """性能跟踪装饰器"""
    def decorator(func):
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            try:
                result = func(*args, **kwargs)
                status = 'success'
                return result
            except Exception as e:
                status = 'error'
                raise
            finally:
                duration = (time.perf_counter() - start) * 1000  # ms
                monitor.record(
                    metric_name,
                    duration,
                    labels={'status': status, 'function': func.__name__}
                )

        return wrapper
    return decorator
```

