## Apache Flink 实战

### Flink DataStream API

```java
// FlinkStreamProcessor.java
import org.apache.flink.api.common.eventtime.*;
import org.apache.flink.streaming.api.datastream.*;
import org.apache.flink.streaming.api.environment.*;
import org.apache.flink.streaming.api.functions.source.*;
import org.apache.flink.streaming.api.windowing.assigners.*;

public class FlinkStreamProcessor {

    public static void main(String[] args) throws Exception {
        final StreamExecutionEnvironment env =
            StreamExecutionEnvironment.getExecutionEnvironment();

        env.setParallelism(4);

        // 1. 从 Kafka 读取数据
        DataStream<Event> events = env.addSource(new EventSource());

        // 2. 提取时间戳和水位线
        DataStream<Event> withTimestamps = events
            .assignTimestampsAndWatermarks(
                WatermarkStrategy
                    .<Event>forBoundedOutOfOrderness(Duration.ofSeconds(5))
                    .withTimestampAssigner((event, timestamp) -> event.timestamp)
            );

        // 3. 过滤和转换
        DataStream<Event> filtered = withTimestamps
            .filter(event -> event.value > 100)
            .map(event -> new EnrichedEvent(
                event.id,
                event.type,
                event.value * 2,
                event.timestamp
            ));

        // 4. KeyBy 和窗口聚合
        DataStream<AggregatedResult> aggregated = filtered
            .keyBy(event -> event.type)
            .window(TumblingEventTimeWindows.of(Time.minutes(5)))
            .aggregate(new EventAggregator());

        aggregated.print();

        env.execute("Flink Stream Processing");
    }

    public static class Event {
        public String id;
        public String type;
        public double value;
        public long timestamp;
    }

    public static class AggregatedResult {
        public String type;
        public long count;
        public double sum;
        public double average;
        public long windowEnd;
    }
}
```

