### Flink CEP

```java
// FlinkCEPProcessor.java
import org.apache.flink.cep.*;
import org.apache.flink.cep.pattern.*;
import org.apache.flink.cep.pattern.conditions.*;
import org.apache.flink.streaming.api.datastream.*;

public class FlinkCEPProcessor {

    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env =
            StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<Event> events = env.addSource(new EventSource());

        // 定义模式：检测失败的登录尝试
        Pattern<Event, ?> failedLoginPattern = Pattern.<Event>begin("failed")
            .subtype(Event.class)
            .where(evt -> "login_failed".equals(evt.type))
            .times(3)
            .within(Time.minutes(5));

        // 检测模式
        PatternStream<Event> patternStream = CEP.pattern(
            events.keyBy(Event::getUserId),
            failedLoginPattern
        );

        // 处理匹配
        DataStream<Alert> alerts = patternStream.select(
            (Map<String, List<Event>> pattern) -> {
                List<Event> failedAttempts = pattern.get("failed");
                return new Alert(
                    "multiple_failed_logins",
                    failedAttempts.get(0).userId,
                    String.format(
                        "User %s has %d failed login attempts",
                        failedAttempts.get(0).userId,
                        failedAttempts.size()
                    )
                );
            }
        );

        alerts.print();

        env.execute("Flink CEP Example");
    }
}
```

## Spark Structured Streaming

### Structured Streaming API

```scala
// SparkStructuredStreaming.scala
import org.apache.spark.sql.SparkSession
import org.apache.spark.sql.functions._
import org.apache.spark.sql.streaming.Trigger
import org.apache.spark.sql.types._

object SparkStructuredStreaming {
  def main(args: Array[String]): Unit = {
    val spark = SparkSession.builder()
      .appName("StructuredStreaming")
      .master("local[4]")
      .getOrCreate()

    import spark.implicits._

    // 从 Kafka 读取
    val df = spark.readStream
      .format("kafka")
      .option("kafka.bootstrap.servers", "localhost:9092")
      .option("subscribe", "events")
      .option("startingOffsets", "latest")
      .load()

    // 解析 JSON
    val schema = new StructType()
      .add("event_id", StringType)
      .add("event_type", StringType)
      .add("value", DoubleType)
      .add("timestamp", LongType)

    val events = df
      .select(from_json($("value").cast("string"), schema).as("event"))
      .select("event.*")
      .withWatermark("timestamp", "5 minutes")

    // 窗口聚合
    val aggregated = events
      .groupBy(
        window($("timestamp"), "5 minutes"),
        $("event_type")
      )
      .agg(
        count("*").as("count"),
        sum("value").as("total"),
        avg("value").as("average")
      )

    // 输出到 Kafka
    val query = aggregated.writeStream
      .format("kafka")
      .option("kafka.bootstrap.servers", "localhost:9092")
      .option("topic", "aggregated_events")
      .option("checkpointLocation", "/tmp/checkpoint")
      .trigger(Trigger.ProcessingTime("1 minute"))
      .start()

    query.awaitTermination()
  }
}
```

