# JavaScript异步编程完全指南

JavaScript的单线程特性使得异步编程成为前端开发的核心技能。本教程将带你深入理解JavaScript异步编程的各个方面。

## 理解JavaScript执行模型

### 单线程与事件循环

JavaScript是单线程语言，意味着同一时间只能执行一个任务。但通过事件循环（Event Loop），可以实现异步操作：

```javascript
// 同步代码
console.log('1');
console.log('2');
console.log('3');

// 输出: 1, 2, 3
```

```javascript
// 异步代码
console.log('1');

setTimeout(() => {
  console.log('2');
}, 0);

console.log('3');

// 输出: 1, 3, 2
```

### 事件循环机制

```
┌─────────────────────────────┐
│         Call Stack          │  // 执行上下文栈
│  ┌─────────────────────┐    │
│  │   Current Task      │    │
│  └─────────────────────┘    │
└──────────────┬──────────────┘
               │
               ▼
┌─────────────────────────────┐
│      Web APIs               │  // 浏览器API
│  - setTimeout               │
│  - fetch                    │
│  - DOM Events               │
└──────────────┬──────────────┘
               │
               ▼
┌─────────────────────────────┐
│      Task Queue             │  // 任务队列
│  - Callback Queue           │
│  - Microtask Queue          │
└──────────────┬──────────────┘
               │
               └──────▶ Event Loop
```

### 宏任务与微任务

```javascript
console.log('Script start');

setTimeout(() => {
  console.log('setTimeout');
}, 0);

Promise.resolve()
  .then(() => {
    console.log('Promise 1');
  })
  .then(() => {
    console.log('Promise 2');
  });

console.log('Script end');

// 输出顺序:
// Script start
// Script end
// Promise 1
// Promise 2
// setTimeout
```

**执行顺序**：
1. 同步代码
2. 微任务（Promise.then, queueMicrotask）
3. 宏任务（setTimeout, setInterval, I/O）

## 回调函数（Callback）

### 基础回调

```javascript
function fetchData(callback) {
  setTimeout(() => {
    const data = { id: 1, name: 'John' };
    callback(data);
  }, 1000);
}

fetchData((data) => {
  console.log('Received:', data);
});
```

### 回调地狱

```javascript
// 回调地狱示例
getData((a) => {
  getMoreData(a, (b) => {
    getMoreData(b, (c) => {
      getMoreData(c, (d) => {
        getMoreData(d, (e) => {
          // 嵌套太深！
        });
      });
    });
  });
});
```

### 错误处理

```javascript
// Error-first callback
function fetchData(callback) {
  setTimeout(() => {
    const error = null;
    const data = { id: 1, name: 'John' };
    callback(error, data);
  }, 1000);
}

fetchData((error, data) => {
  if (error) {
    console.error('Error:', error);
    return;
  }
  console.log('Data:', data);
});
```

## Promise

### Promise基础

```javascript
// 创建Promise
const promise = new Promise((resolve, reject) => {
  // 异步操作
  setTimeout(() => {
    const success = true;
    if (success) {
      resolve('Operation successful');
    } else {
      reject('Operation failed');
    }
  }, 1000);
});

// 使用Promise
promise
  .then(result => {
    console.log(result);
  })
  .catch(error => {
    console.error(error);
  });
```

### Promise状态

```javascript
// 三种状态
// 1. pending（进行中）
// 2. fulfilled（已成功）
// 3. rejected（已失败）

const promise1 = new Promise((resolve) => {
  resolve(); // pending → fulfilled
});

const promise2 = new Promise((_, reject) => {
  reject(); // pending → rejected
});

// 状态一旦改变，就不会再变
```

### Promise链式调用

```javascript
// 链式调用
fetchUser(1)
  .then(user => {
    console.log('User:', user);
    return fetchPosts(user.id); // 返回新Promise
  })
  .then(posts => {
    console.log('Posts:', posts);
    return fetchComments(posts[0].id);
  })
  .then(comments => {
    console.log('Comments:', comments);
  })
  .catch(error => {
    console.error('Error:', error);
  });
```

### Promise常用方法

#### Promise.all()

```javascript
// 所有Promise都成功才成功
const promise1 = fetch('/api/user');
const promise2 = fetch('/api/posts');
const promise3 = fetch('/api/comments');

Promise.all([promise1, promise2, promise3])
  .then(responses => {
    console.log('All responses:', responses);
    // responses是一个数组，包含所有Promise的结果
  })
  .catch(error => {
    console.error('One failed:', error);
    // 任何一个失败，都会进入catch
  });
```

#### Promise.allSettled()

```javascript
// 等待所有Promise完成（无论成功失败）
const promises = [
  fetch('/api/user'),
  fetch('/api/posts'),
  fetch('/api/comments')
];

Promise.allSettled(promises)
  .then(results => {
    results.forEach((result, index) => {
      if (result.status === 'fulfilled') {
        console.log(`Promise ${index} succeeded:`, result.value);
      } else {
        console.log(`Promise ${index} failed:`, result.reason);
      }
    });
  });
```

#### Promise.race()

```javascript
// 返回最先完成的Promise结果
const promise1 = new Promise(resolve => {
  setTimeout(() => resolve('Promise 1'), 1000);
});

const promise2 = new Promise(resolve => {
  setTimeout(() => resolve('Promise 2'), 500);
});

Promise.race([promise1, promise2])
  .then(result => {
    console.log(result); // "Promise 2"
  });

// 实际应用：请求超时
function fetchWithTimeout(url, timeout = 5000) {
  const fetchPromise = fetch(url);
  const timeoutPromise = new Promise((_, reject) => {
    setTimeout(() => reject(new Error('Timeout')), timeout);
  });

  return Promise.race([fetchPromise, timeoutPromise]);
}
```

#### Promise.any()

```javascript
// 返回第一个成功的Promise
const promises = [
  Promise.reject('Error 1'),
  Promise.reject('Error 2'),
  Promise.resolve('Success'),
  Promise.reject('Error 3')
];

Promise.any(promises)
  .then(result => {
    console.log(result); // "Success"
  })
  .catch(error => {
    console.error('All failed:', error);
  });
```

### Promise错误处理

```javascript
// 方法1：使用catch
promise
  .then(result => {
    // 处理结果
  })
  .catch(error => {
    // 处理错误
  });

// 方法2：在then中传入两个回调
promise.then(
  result => {
    // 处理结果
  },
  error => {
    // 处理错误
  }
);

// 方法3：使用finally
promise
  .then(result => {
    // 处理结果
  })
  .catch(error => {
    // 处理错误
  })
  .finally(() => {
    // 无论成功失败都会执行
    console.log('Cleanup');
  });
```

### 封装Promise

```javascript
// 封装fetch
function fetchJSON(url) {
  return fetch(url)
    .then(response => {
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      return response.json();
    });
}

// 使用
fetchJSON('/api/users')
  .then(users => console.log(users))
  .catch(error => console.error(error));
```

```javascript
// 封装超时
function delay(ms) {
  return new Promise(resolve => {
    setTimeout(resolve, ms);
  });
}

// 使用
delay(1000).then(() => {
  console.log('1秒后执行');
});
```

```javascript
// 封装重试
function fetchWithRetry(url, maxRetries = 3) {
  return new Promise((resolve, reject) => {
    function attempt(retriesLeft) {
      fetch(url)
        .then(response => {
          if (!response.ok) throw new Error('Not OK');
          return response.json();
        })
        .then(resolve)
        .catch(error => {
          if (retriesLeft <= 0) {
            reject(error);
          } else {
            console.log(`Retrying... (${retriesLeft} left)`);
            setTimeout(() => attempt(retriesLeft - 1), 1000);
          }
        });
    }

    attempt(maxRetries);
  });
}
```

## async/await

### 基础语法

```javascript
// async函数返回Promise
async function fetchData() {
  return 'Data';
}

// 等价于
function fetchData() {
  return Promise.resolve('Data');
}
```

```javascript
// await等待Promise完成
async function getData() {
  const promise = new Promise(resolve => {
    setTimeout(() => resolve('Data'), 1000);
  });

  const result = await promise; // 等待Promise完成
  console.log(result); // 'Data'
}
```

### 错误处理

```javascript
// 方法1：使用try-catch
async function fetchData() {
  try {
    const response = await fetch('/api/data');
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Error:', error);
    throw error;
  }
}

// 方法2：使用.catch()
fetchData()
  .then(data => console.log(data))
  .catch(error => console.error(error));
```

### 并行执行

```javascript
// 串行执行（慢）
async function fetchAllSerial() {
  const user = await fetchUser();
  const posts = await fetchPosts();
  const comments = await fetchComments();
  return { user, posts, comments };
}

// 并行执行（快）
async function fetchAllParallel() {
  const [user, posts, comments] = await Promise.all([
    fetchUser(),
    fetchPosts(),
    fetchComments()
  ]);
  return { user, posts, comments };
}
```

### 循环中的异步

```javascript
// 方法1：for...of（串行）
async function processItems(items) {
  for (const item of items) {
    await processItem(item);
  }
}

// 方法2：for...of（并行）
async function processItems(items) {
  const promises = items.map(item => processItem(item));
  await Promise.all(promises);
}

// 方法3：for循环（串行）
async function processItems(items) {
  for (let i = 0; i < items.length; i++) {
    await processItem(items[i]);
  }
}

// 方法4：forEach（不推荐）
async function processItems(items) {
  items.forEach(async (item) => {
    await processItem(item); // 不会等待！
  });
}
```

### 实际应用案例

#### 数据获取

```javascript
class APIClient {
  async get(url) {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    return response.json();
  }

  async post(url, data) {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    return response.json();
  }

  async delete(url) {
    const response = await fetch(url, {
      method: 'DELETE'
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    return response.json();
  }
}

// 使用
const api = new APIClient();

async function loadDashboard() {
  try {
    const [user, stats, notifications] = await Promise.all([
      api.get('/api/user'),
      api.get('/api/stats'),
      api.get('/api/notifications')
    ]);

    return { user, stats, notifications };
  } catch (error) {
    console.error('Failed to load dashboard:', error);
  }
}
```

#### 表单提交

```javascript
async function submitForm(formData) {
  try {
    // 验证
    const validation = await validateForm(formData);
    if (!validation.valid) {
      throw new Error(validation.errors.join(', '));
    }

    // 提交
    const response = await fetch('/api/submit', {
      method: 'POST',
      body: JSON.stringify(formData)
    });

    if (!response.ok) {
      throw new Error('Submission failed');
    }

    const result = await response.json();
    return result;
  } catch (error) {
    console.error('Form submission error:', error);
    throw error;
  }
}
```

#### 批量处理

```javascript
async function processBatch(items, batchSize = 5) {
  const results = [];

  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize);
    const batchResults = await Promise.all(
      batch.map(item => processItem(item))
    );
    results.push(...batchResults);
  }

  return results;
}
```

## 异步迭代

### for await...of

```javascript
// 异步生成器
async function* fetchPages(baseUrl) {
  let page = 1;
  while (true) {
    const response = await fetch(`${baseUrl}?page=${page}`);
    const data = await response.json();

    if (data.items.length === 0) break;

    yield data.items;
    page++;
  }
}

// 使用异步迭代
async function fetchAllPages() {
  const allItems = [];

  for await (const pageItems of fetchPages('/api/items')) {
    allItems.push(...pageItems);
  }

  return allItems;
}
```

## 最佳实践

### 1. 总是处理错误

```javascript
// 不好：忽略错误
fetch('/api/data').then(data => {
  console.log(data);
});

// 好：处理错误
fetch('/api/data')
  .then(data => {
    console.log(data);
  })
  .catch(error => {
    console.error(error);
  });
```

### 2. 避免在循环中使用await

```javascript
// 不好：串行执行
for (const url of urls) {
  await fetch(url);
}

// 好：并行执行
await Promise.all(urls.map(url => fetch(url)));
```

### 3. 使用Promise.allSettled处理部分失败

```javascript
const results = await Promise.allSettled(
  urls.map(url => fetch(url))
);

results.forEach((result, index) => {
  if (result.status === 'fulfilled') {
    console.log(`URL ${index} succeeded`);
  } else {
    console.log(`URL ${index} failed:`, result.reason);
  }
});
```

### 4. 避免嵌套Promise

```javascript
// 不好：嵌套
fetchUser()
  .then(user => {
    fetchPosts(user.id)
      .then(posts => {
        fetchComments(posts[0].id)
          .then(comments => {
            // 嵌套太深
          });
      });
  });

// 好：扁平化
fetchUser()
  .then(user => fetchPosts(user.id))
  .then(posts => fetchComments(posts[0].id))
  .then(comments => {
    // 扁平化
  });
```

### 5. 使用async函数而不是直接返回Promise

```javascript
// 不好：返回Promise
function fetchData() {
  return fetch('/api/data').then(r => r.json());
}

// 好：使用async
async function fetchData() {
  const response = await fetch('/api/data');
  return response.json();
}
```

## 性能优化

### 请求去重

```javascript
const pendingRequests = new Map();

async function fetchOnce(url) {
  if (pendingRequests.has(url)) {
    return pendingRequests.get(url);
  }

  const promise = fetch(url)
    .then(response => response.json())
    .finally(() => {
      pendingRequests.delete(url);
    });

  pendingRequests.set(url, promise);
  return promise;
}
```

### 缓存结果

```javascript
const cache = new Map();

async function fetchWithCache(url) {
  if (cache.has(url)) {
    return cache.get(url);
  }

  const data = await fetch(url).then(r => r.json());
  cache.set(url, data);
  return data;
}
```

### 请求取消

```javascript
async function fetchWithTimeout(url, timeout = 5000) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);

  try {
    const response = await fetch(url, {
      signal: controller.signal
    });
    clearTimeout(timeoutId);
    return response.json();
  } catch (error) {
    if (error.name === 'AbortError') {
      throw new Error('Request timeout');
    }
    throw error;
  }
}
```

