### 表单验证

```typescript
type ValidationResult<T> = {
  [K in keyof T]?: string[];
};

interface ValidationRule<T> {
  validate: (value: T) => boolean;
  message: string;
}

interface FormField<T> {
  value: T;
  rules: ValidationRule<T>[];
}

class Form<T extends Record<string, any>> {
  private fields: { [K in keyof T]: FormField<T[K]> };

  constructor(initialValues: T) {
    this.fields = {} as any;
    for (const key in initialValues) {
      this.fields[key] = {
        value: initialValues[key],
        rules: []
      };
    }
  }

  addRule<K extends keyof T>(
    field: K,
    rule: ValidationRule<T[K]>
  ): void {
    this.fields[field].rules.push(rule);
  }

  validate(): ValidationResult<T> | null {
    const errors: any = {};

    for (const key in this.fields) {
      const field = this.fields[key];
      const fieldErrors: string[] = [];

      for (const rule of field.rules) {
        if (!rule.validate(field.value)) {
          fieldErrors.push(rule.message);
        }
      }

      if (fieldErrors.length > 0) {
        errors[key] = fieldErrors;
      }
    }

    return Object.keys(errors).length > 0 ? errors : null;
  }

  getValues(): T {
    const values = {} as T;
    for (const key in this.fields) {
      values[key] = this.fields[key].value;
    }
    return values;
  }
}

// 使用
interface LoginForm {
  email: string;
  password: string;
}

const loginForm = new Form<LoginForm>({
  email: "",
  password: ""
});

loginForm.addRule("email", {
  validate: (value) => /^[^@]+@[^@]+$/.test(value),
  message: "Invalid email format"
});

loginForm.addRule("password", {
  validate: (value) => value.length >= 8,
  message: "Password must be at least 8 characters"
});

const errors = loginForm.validate();
```

### 状态管理

```typescript
type StateUpdater<T> = (current: T) => T;

class Store<T> {
  private state: T;
  private listeners: Set<(state: T) => void> = new Set();

  constructor(initialState: T) {
    this.state = initialState;
  }

  getState(): T {
    return this.state;
  }

  setState(updater: StateUpdater<T>): void {
    this.state = updater(this.state);
    this.notify();
  }

  subscribe(listener: (state: T) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private notify(): void {
    this.listeners.forEach(listener => listener(this.state));
  }
}

// 使用
interface AppState {
  user: User | null;
  isLoading: boolean;
  error: string | null;
}

const store = new Store<AppState>({
  user: null,
  isLoading: false,
  error: null
});

store.subscribe((state) => {
  console.log("State changed:", state);
});

store.setState((current) => ({
  ...current,
  isLoading: true
}));
```

## 泛型最佳实践

### 1. 使用有意义的类型参数名

```typescript
// 不好
function identity<T>(value: T): T {
  return value;
}

// 好
function identity<TType>(value: TType): TType {
  return value;
}

// 更好：使用描述性名称
function getFirstElement<TElement>(array: TElement[]): TElement | undefined {
  return array[0];
}
```

### 2. 提供合理的默认值

```typescript
// 不好：必须总是指定类型
interface Container<T> {
  value: T;
}

// 好：提供默认值
interface Container<T = any> {
  value: T;
}
```

### 3. 使用约束而不是any

```typescript
// 不好：使用any
function logLength<T>(value: any): void {
  console.log(value.length);
}

// 好：使用约束
interface HasLength {
  length: number;
}

function logLength<T extends HasLength>(value: T): void {
  console.log(value.length);
}
```

### 4. 考虑使用 keyof 操作符

```typescript
// 不好：字符串字面量
function getProperty(obj: any, key: string): any {
  return obj[key];
}

// 好：使用keyof
function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}
```

### 5. 避免过度使用泛型

```typescript
// 不好：不必要的泛型
function greet<T extends string>(name: T): string {
  return `Hello, ${name}!`;
}

// 好：简单类型
function greet(name: string): string {
  return `Hello, ${name}!`;
}
```

## 常见问题

### Q: 何时使用泛型？

A: 使用泛型的场景：
- 函数可以处理多种类型
- 需要保持类型安全
- 代码需要在多种类型上复用
- 需要在类型之间建立关系

### Q: 泛型会影响性能吗？

A: 不会。TypeScript的泛型在编译时被擦除，不会影响运行时性能。

### Q: 泛型和联合类型有什么区别？

A:
- **泛型**：一种类型，可以在使用时指定
- **联合类型**：多种类型之一

```typescript
// 泛型
function identity<T>(value: T): T {
  return value;
}

// 联合类型
function print(value: string | number): void {
  console.log(value);
}
```

