  logger.info('Important business event');
  logger.warn('Warning that needs attention');
  logger.error('Error that needs fixing');
}
```

### 5. 异步日志记录

```javascript
// 使用异步传输
const logger = winston.createLogger({
  transports: [
    new winston.transports.File({
      filename: 'app.log',
      tailable: true,
      maxsize: 100 * 1024 * 1024,  // 100MB
      maxFiles: 10
    })
  ]
});
```

### 6. 日志采样

```javascript
// 高频日志采样
