# MongoDB高级特性

MongoDB是最流行的NoSQL文档数据库，本教程将深入讲解MongoDB的高级特性和最佳实践。

## 聚合管道（Aggregation Pipeline）

### 基本概念

聚合管道是MongoDB的数据处理框架，支持复杂的数据转换和计算。

```javascript
// 基本结构
db.collection.aggregate([
  { $stage1: { ... } },
  { $stage2: { ... } },
  { $stage3: { ... } }
])
```

### 常用阶段操作符

#### $match（过滤）

```javascript
db.orders.aggregate([
  { $match: { status: "completed", total: { $gte: 100 } } }
])
```

#### $group（分组）

```javascript
// 按产品分组统计销售额
db.orders.aggregate([
  {
    $group: {
      _id: "$product_id",
      totalSales: { $sum: "$amount" },
      count: { $sum: 1 },
      avgAmount: { $avg: "$amount" }
    }
  }
])

// 多字段分组
db.orders.aggregate([
  {
    $group: {
      _id: { category: "$category", year: { $year: "$date" } },
      total: { $sum: "$amount" }
    }
  }
])
```

#### $project（投影）

```javascript
db.users.aggregate([
  {
    $project: {
      name: 1,
      email: 1,
      fullName: { $concat: ["$firstName", " ", "$lastName"] },
      age: {
        $subtract: [
          { $year: new Date() },
          { $year: "$birthDate" }
        ]
      }
    }
  }
])
```

#### $lookup（左连接）

```javascript
db.orders.aggregate([
  {
    $lookup: {
      from: "users",
      localField: "user_id",
      foreignField: "_id",
      as: "user"
    }
  },
  {
    $unwind: "$user"  // 将数组展开为对象
  },
  {
    $project: {
      order_id: 1,
      total: 1,
      "user.name": 1,
      "user.email": 1
    }
  }
])
```

#### $unwind（展开数组）

```javascript
db.users.aggregate([
  { $unwind: "$tags" },
  { 
    $group: {
      _id: "$tags",
      count: { $sum: 1 }
    }
  }
])
```

### 复杂聚合示例

#### 销售漏斗分析

```javascript
db.users.aggregate([
  // 访问网站
  { $match: { visited: true } },
  { $count: "visited" },

  // 加入购物车
  { $match: { cart_items: { $exists: true, $ne: [] } } },
  { $count: "added_to_cart" },

  // 完成购买
  { $match: { purchases: { $exists: true } } },
  { $count: "purchased" }
])
```

#### 时间序列聚合

```javascript
db.sensor_data.aggregate([
  {
    $group: {
      _id: {
        sensor: "$sensor_id",
        hour: {
          $dateToString: {
            format: "%Y-%m-%d %H:00:00",
            date: "$timestamp"
          }
        }
      },
      avgValue: { $avg: "$value" },
      maxValue: { $max: "$value" },
      minValue: { $min: "$value" },
      count: { $sum: 1 }
    }
  },
  { $sort: { "_id.hour": 1 } }
])
```

#### 分页查询

```javascript
db.products.aggregate([
  // 匹配条件
  { $match: { category: "electronics" } },

  // 排序
  { $sort: { price: -1 } },

  // 跳过（用于分页）
  { $skip: 20 },

  // 限制（每页数量）
  { $limit: 10 },

  // 获取总数
  {
    $facet: {
      data: [
        { $skip: 20 },
        { $limit: 10 }
      ],
      totalCount: [
        { $count: "count" }
      ]
    }
  }
])
```

