## 查询DSL

### 基础查询

```json
// match查询（分词后搜索）
GET /articles/_search
{
  "query": {
    "match": {
      "title": "Elasticsearch入门"
    }
  }
}

// multi_match（多字段搜索）
GET /articles/_search
{
  "query": {
    "multi_match": {
      "query": "搜索引擎",
      "fields": ["title^2", "content"],  // title权重×2
      "type": "best_fields"
    }
  }
}

// term查询（精确匹配）
GET /articles/_search
{
  "query": {
    "term": {
      "tags.keyword": "elasticsearch"
    }
  }
}

// terms查询（多值匹配）
GET /articles/_search
{
  "query": {
    "terms": {
      "tags.keyword": ["elasticsearch", "postgresql"]
    }
  }
}

// range查询
GET /articles/_search
{
  "query": {
    "range": {
      "views": {
        "gte": 1000,
        "lte": 10000
      }
    }
  }
}
```

### 布尔查询

```json
// must（必须匹配）
GET /articles/_search
{
  "query": {
    "bool": {
      "must": [
        { "match": { "title": "elasticsearch" } },
        { "range": { "views": { "gte": 1000 } } }
      ]
    }
  }
}

// should（至少匹配一个）
GET /articles/_search
{
  "query": {
    "bool": {
      "should": [
        { "match": { "title": "elasticsearch" } },
        { "match": { "content": "elasticsearch" } }
      ],
      "minimum_should_match": 1
    }
  }
}

// must_not（必须不匹配）
GET /articles/_search
{
  "query": {
    "bool": {
      "must": { "match": { "title": "教程" } },
      "must_not": { "term": { "tags.keyword": "广告" } }
    }
  }
}

// filter（不计算评分）
GET /articles/_search
{
  "query": {
    "bool": {
      "filter": [
        { "term": { "status.keyword": "published" } },
        { "range": { "publish_date": { "gte": "2024-01-01" } } }
      ]
    }
  }
}
```

