## 应用集成

### OpenTelemetry集成（推荐）

OpenTelemetry是CNCF的统一可观测性标准。

#### Node.js集成

```bash
# 安装依赖
npm install @opentelemetry/api \
  @opentelemetry/sdk-node \
  @opentelemetry/auto-instrumentations
```

```javascript
// tracing.js
const { NodeSDK } = require('@opentelemetry/sdk-node');
const { getResource } = require('@opentelemetry/resources');
const {
  SemanticResourceAttributes,
} = require('@opentelemetry/semantic-conventions');
const { JaegerExporter } = require('@opentelemetry/exporter-trace-jaeger');

// 创建Jaeger导出器
const jaegerExporter = new JaegerExporter({
  endpoint: 'http://localhost:14268/api/traces',
});

// 初始化SDK
const sdk = new NodeSDK({
  resource: getResource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'my-service',
  }),
  traceExporter: jaegerExporter,
});

sdk.start();
```

#### Python集成

```bash
pip install opentelemetry-api \
  opentelemetry-sdk \
  opentelemetry-instrumentation-flask \
  opentelemetry-exporter-jaeger
```

```python
from opentelemetry import trace
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import JaegerExporter
from opentelemetry.sdk.resources import SERVICE_NAME, Resource
from flask import Flask

# 配置资源
resource = Resource(attributes={
    SERVICE_NAME: "my-service"
})

# 配置provider
trace.set_tracer_provider(TracerProvider(resource=resource))
tracer = trace.get_tracer(__name__)

# 配置Jaeger导出器
jaeger_exporter = JaegerExporter(
    agent_host_name="localhost",
    agent_port=6831,
)

# 创建Flask应用
app = Flask(__name__)

@app.route("/api/users")
def get_users():
    with tracer.start_as_current_span("get-users-operation"):
        # 业务逻辑
        return jsonify({"users": []})
```

#### Go集成

```go
import (
    "context"
    "github.com/opentracing/opentracing-go"
    "github.com/uber/jaeger-client-go"
    jaegercfg "github.com/uber/jaeger-client-go/config"
)

func initTracer(serviceName string) (opentracing.Tracer, io.Closer, error) {
    cfg := jaegercfg.Configuration{
        ServiceName: serviceName,
        Sampler: &jaegercfg.SamplerConfig{
            Type:  jaeger.SamplerTypeConst,
            Param: 1,
        },
        Reporter: &jaegercfg.ReporterConfig{
            LogSpans: true,
        },
    }
    return cfg.NewTracer()
}

func main() {
    tracer, closer, err := initTracer("my-service")
    defer closer.Close()
    opentracing.InitGlobalTracer(tracer)
}
```

## 创建Span

### 手动创建Span

```javascript
// 创建根Span
const span = tracer.startSpan('http-request');

// 添加标签
span.setTag('http.method', 'GET');
span.setTag('http.url', '/api/users');

// 添加日志
span.log({
  event: 'cache_miss',
  message: 'Cache not found, querying database'
});

// 完成Span
span.finish();
```

### 嵌套Span

```javascript
// 父Span
const parentSpan = tracer.startSpan('process-order');

// 使用父Span创建子Span
const childSpan = tracer.startSpan('check-inventory', {
  childOf: parentSpan.context()
});

childSpan.finish();
parentSpan.finish();
```

### 上下文传播

```javascript
// 服务A：创建Span并注入到HTTP头
const span = tracer.startSpan('http-request');
const headers = {};
tracer.inject(span.context(), opentracing.FORMAT_HTTP_HEADERS, headers);

// 发送HTTP请求时携带headers
fetch('http://service-b/api', { headers });

// 服务B：从HTTP头提取Span上下文
const wireContext = tracer.extract(
  opentracing.FORMAT_HTTP_HEADERS,
  request.headers
);
const span = tracer.startSpan('handle-request', { childOf: wireContext });
```

